%=============================================================================
% Pack the spoken WAV clips (0-9, A-Z) generated by generate_voice_clips.ps1
% into a single voice_clips.mat next to the demo, so the example ships one data
% file instead of 36 loose WAVs. Samples are stored as int16 to keep the file
% small; the demo converts them back to double before playing.
%   1) powershell -ExecutionPolicy Bypass -File generate_voice_clips.ps1
%   2) run this (headless): pack_voice_clips()
function pack_voice_clips()
  thisDir = fileparts(mfilename('fullpath'));
  parent = fileparts(thisDir);
  labels = ['0':'9', 'A':'Z'];
  clips.labels = labels;
  clips.Y = cell(1, numel(labels));
  clips.Fs = zeros(1, numel(labels));
  for i = 1:numel(labels)
    [y, fs] = audioread(fullfile(thisDir, [labels(i), '.wav']));
    y = min(1, max(-1, y(:, 1)));
    clips.Y{i} = int16(round(y * 32767));
    clips.Fs(i) = fs;
  end
  outFile = fullfile(parent, 'voice_clips.mat');
  save(outFile, 'clips');
  fprintf('Packed %d clips into %s\n', numel(labels), outFile);
end
%=============================================================================
